//! Exact witness and receipt attachment fixtures generated by the pinned keripy reference.
//!
//! The pinned signify-ts reference cannot emit witness indexed-signature groups or
//! non-transferable receipt couples, so these two group kinds are verified against keripy
//! instead. See ADR 0009 and `fixtures/keri-attachment-keripy/README.md`.

use std::error::Error;

use serde::Deserialize;
use signify_cesr::sequence::SequenceNumber;
use signify_crypto::signature::{IndexedSignature, UnindexedSignature};
use signify_crypto::verifier::VerificationKey;
use signify_keri::attachment::{
    AttachmentError, AttachmentFraming, ReceiptCouple, SignatureSeal, SignedMessageBuilder,
};
use signify_keri::prefix::IdentifierPrefix;
use signify_keri::said::Said;
use signify_keri::serialization::SerializedEvent;

const REFERENCE_SHA: &str = "4ce4cc79e06653f77342be1bf604086b89b1f090";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    reference_version: String,
    generated_on: String,
    sources: Vec<String>,
    signatures: Signatures,
    cases: Vec<MessageCase>,
    rejected_cases: Vec<RejectedCase>,
    reference_facts: ReferenceFacts,
}

#[derive(Debug, Deserialize)]
struct Signatures {
    controller: String,
    witness_seeds_hex: Vec<String>,
    witness_verfers: Vec<String>,
    witness_indexed: Vec<String>,
    receipt_unindexed: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct MessageCase {
    name: String,
    event: String,
    attachments: String,
    controller_signature_count: usize,
    witness_signature_count: usize,
    receipt_couple_count: usize,
    seal_kind: Option<String>,
    pipelined: bool,
    raw: String,
    raw_hex: String,
    raw_byte_size: usize,
}

#[derive(Debug, Deserialize)]
struct RejectedCase {
    name: String,
    reference_error_category: String,
    reference_error_message: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceFacts {
    code_b_is_in_non_trans_dex: bool,
    non_transferable_codex_values: Vec<String>,
    witness_counter_code: String,
    receipt_couple_counter_code: String,
    note: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/keri-attachment-keripy/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

fn witness_signatures(fixture: &Fixture, count: usize) -> Result<Vec<IndexedSignature>, Box<dyn Error>> {
    fixture
        .signatures
        .witness_indexed
        .iter()
        .zip(&fixture.signatures.witness_verfers)
        .take(count)
        .map(|(signature, verfer)| {
            Ok(IndexedSignature::from_qb64(signature)?.with_verifier(VerificationKey::from_qb64(verfer)?)?)
        })
        .collect()
}

fn receipt_couples(fixture: &Fixture, count: usize) -> Result<Vec<ReceiptCouple>, Box<dyn Error>> {
    fixture
        .signatures
        .receipt_unindexed
        .iter()
        .zip(&fixture.signatures.witness_verfers)
        .take(count)
        .map(|(signature, verfer)| {
            Ok(ReceiptCouple::new(
                VerificationKey::from_qb64(verfer)?,
                UnindexedSignature::from_qb64(signature)?,
            )?)
        })
        .collect()
}

/// Rebuilds one fixture case through the Rust builder.
fn build_case(case: &MessageCase, fixture: &Fixture) -> Result<Vec<u8>, Box<dyn Error>> {
    let event = SerializedEvent::parse(case.event.as_bytes())?;
    let mut builder = SignedMessageBuilder::new(&event);
    if case.controller_signature_count > 0 {
        assert_eq!(
            case.controller_signature_count, 1,
            "fixture uses one controller signature"
        );
        builder = builder.controller_signatures(vec![IndexedSignature::from_qb64(&fixture.signatures.controller)?]);
    }
    if let Some(kind) = &case.seal_kind {
        assert_eq!(kind, "SealEvent", "fixture seals are SealEvent");
        builder = builder.seal(SignatureSeal::Event {
            identifier: IdentifierPrefix::from_qb64(
                event.sad().get_text("i").ok_or("fixture event carries no identifier")?,
            )?,
            sequence_number: SequenceNumber::from_hex(
                event.sad().get_text("s").ok_or("fixture event carries no sequence")?,
            )?,
            said: Said::from_qb64(event.sad().get_text("d").ok_or("fixture event carries no SAID")?)?,
        });
    }
    if case.witness_signature_count > 0 {
        builder = builder.witness_signatures(witness_signatures(fixture, case.witness_signature_count)?);
    }
    if case.receipt_couple_count > 0 {
        builder = builder.receipt_couples(receipt_couples(fixture, case.receipt_couple_count)?);
    }
    if case.pipelined {
        builder = builder.framing(AttachmentFraming::Pipelined);
    }
    Ok(builder.build()?.into_bytes())
}

#[test]
fn fixture_metadata_matches_the_pinned_keripy_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/keripy.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_eq!(fixture.reference_version, "1.3.6");
    assert!(!fixture.generated_on.is_empty());
    assert_eq!(
        fixture.sources,
        ["src/keri/core/eventing.py", "src/keri/core/coring.py"]
    );
    // The deterministic witness seeds are the byte sequences 0..31 and 32..63.
    assert_eq!(fixture.signatures.witness_seeds_hex.len(), 2);
    let expected_seeds: [Vec<u8>; 2] = [(0..32).collect(), (32..64).collect()];
    for (seed_hex, expected) in fixture.signatures.witness_seeds_hex.iter().zip(&expected_seeds) {
        assert_eq!(&decode_hex(seed_hex)?, expected);
    }
    Ok(())
}

#[test]
fn every_keripy_message_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 9);

    for case in &fixture.cases {
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);
        assert_eq!(expected.len(), case.raw_byte_size, "case {}", case.name);
        assert_eq!(
            format!("{}{}", case.event, case.attachments),
            case.raw,
            "case {} halves do not reassemble",
            case.name
        );

        let built = build_case(case, &fixture)?;
        assert_eq!(
            core::str::from_utf8(&built)?,
            case.raw,
            "case {} bytes differ",
            case.name
        );
    }
    Ok(())
}

#[test]
fn the_witness_and_receipt_counters_are_their_own_codes() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.reference_facts.witness_counter_code, "-B");
    assert_eq!(fixture.reference_facts.receipt_couple_counter_code, "-C");

    let witness_case = fixture
        .cases
        .iter()
        .find(|case| case.name == "witness_only")
        .ok_or("fixture has no witness_only case")?;
    assert!(witness_case.attachments.starts_with("-BAB"));
    let receipt_case = fixture
        .cases
        .iter()
        .find(|case| case.name == "receipt_couple")
        .ok_or("fixture has no receipt_couple case")?;
    assert!(receipt_case.attachments.starts_with("-CAB"));
    // A receipt couple is the qualified key followed by the qualified signature.
    let verfer = fixture
        .signatures
        .witness_verfers
        .first()
        .ok_or("fixture has no witness verfer")?;
    let unindexed = fixture
        .signatures
        .receipt_unindexed
        .first()
        .ok_or("fixture has no receipt signature")?;
    assert_eq!(receipt_case.attachments, format!("-CAB{verfer}{unindexed}"));
    Ok(())
}

#[test]
fn keripy_rejections_map_to_stable_rust_error_categories() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let event = SerializedEvent::parse(fixture.cases.first().ok_or("fixture has no cases")?.event.as_bytes())?;
    let transferable = VerificationKey::from_qb64(
        &fixture
            .signatures
            .witness_verfers
            .first()
            .ok_or("fixture has no witness verfer")?
            .replacen('B', "D", 1),
    )?;
    assert!(transferable.is_transferable());

    for case in &fixture.rejected_cases {
        assert_eq!(case.reference_error_category, "ValueError", "case {}", case.name);
        let error = match case.rust_error_category.as_str() {
            "TransferableReceiptKey" => {
                assert!(case.reference_error_message.contains("tranferable prefix"));
                ReceiptCouple::new(
                    transferable.clone(),
                    UnindexedSignature::from_qb64(
                        fixture
                            .signatures
                            .receipt_unindexed
                            .first()
                            .ok_or("fixture has no receipt signature")?,
                    )?,
                )
                .err()
                .ok_or("a transferable receipt key was accepted")?
            }
            "TransferableWitnessKey" => {
                assert!(case.reference_error_message.contains("tranferable prefix"));
                let signature = IndexedSignature::from_qb64(
                    fixture
                        .signatures
                        .witness_indexed
                        .first()
                        .ok_or("fixture has no witness signature")?,
                )?
                .with_verifier(transferable.clone())?;
                SignedMessageBuilder::new(&event)
                    .witness_signatures(vec![signature])
                    .build()
                    .err()
                    .ok_or("a transferable witness key was accepted")?
            }
            "MissingSignatures" => {
                assert!(case.reference_error_message.contains("Missing attached signatures"));
                SignedMessageBuilder::new(&event)
                    .build()
                    .err()
                    .ok_or("an unsigned message was accepted")?
            }
            other => return Err(format!("unmapped rejection category {other}").into()),
        };
        let category = match error {
            AttachmentError::TransferableReceiptKey => "TransferableReceiptKey",
            AttachmentError::TransferableWitnessKey { .. } => "TransferableWitnessKey",
            AttachmentError::MissingSignatures => "MissingSignatures",
            other => return Err(format!("unexpected error {other}").into()),
        };
        assert_eq!(category, case.rust_error_category, "case {}", case.name);
    }
    Ok(())
}

#[test]
fn the_python_guard_is_reachable_where_the_typescript_guard_is_not() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    // `'B' in NonTransDex` is true in Python -- the same expression whose JavaScript translation
    // is pinned false in fixtures/keri-attachment/v1.json. That contrast is the entire reason
    // this fixture exists.
    assert!(fixture.reference_facts.code_b_is_in_non_trans_dex);
    assert_eq!(
        fixture.reference_facts.non_transferable_codex_values,
        ["B", "1AAA", "1AAC", "1AAI"]
    );
    assert!(fixture.reference_facts.note.contains("ADR 0009"));
    Ok(())
}
